 const filters=node('div',undefined,'sales-filters'),label=node('label','Meta em acompanhamento'),select=node('select');for(const g of goals){const option=node('option',`${g.nome} · ${date(g.inicio)} a ${date(g.fim)}`);option.value=identity(g);select.append(option);}select.value=state.id;label.append(select);filters.append(label,node('small','De/Até seleciona metas; o realizado considera o período integral de cada meta.','sales-card-note'));root.append(filters);
 const content=node('div',undefined,'portfolio-content goals-content');root.append(content);const tracking=goals.map(g=>({...g,...goalTracking(current,g,today)})),v=goalTracking(current,focused,today),metrics=node('div',undefined,'metrics overview-metrics portfolio-metrics');
 for(const [title,value,note] of [['Metas no período',goals.length,'Metas que intersectam o filtro'],['Atingidas',tracking.filter(g=>g.status==='Atingida').length,'Objetivo alcançado'],['Em andamento',tracking.filter(g=>g.status==='Em andamento').length,'Dentro do prazo'],['Prazo encerrado',tracking.filter(g=>g.status==='Prazo encerrado').length,'Objetivo ainda não alcançado']].sort((a,b)=>b[1]-a[1]))metrics.append(card(title,String(value),note));content.append(metrics);
 const grid=node('div',undefined,'portfolio-grid goals-grid'),progress=panel(focused.nome);progress.classList.add('goal-focus','goal-tone-'+v.tone);const badge=node('span',v.status,'state-badge state-'+v.tone);progress.querySelector('h3').append(badge);const focus=node('div',undefined,'goal-focus-body'),stats=node('div',undefined,'goal-focus-values');focus.append(goalGauge(v.percent));for(const [title,value] of [['Objetivo',focused.valor_centavos],['Realizado',v.realized],['Falta',v.remaining]].sort((a,b)=>b[1]-a[1])){const item=node('div',undefined,'sales-highlight');item.append(node('span',title),node('strong',money(value)));stats.append(item);}focus.append(stats);progress.append(focus,node('small',`${date(focused.inicio)} a ${date(focused.fim)}${v.provisional?' · inclui valores provisórios do dia aberto':''}`,'sales-card-note'));grid.append(progress);
 const trend=panel('Evolução acumulada da meta'),series=goalSeries(current,focused,today);trend.append(goalTrendChart(series),node('small','● Verde: realizado · linha tracejada: ritmo esperado por dia de calendário. Não projeta vendas futuras.','sales-card-note'));grid.append(trend);
 const list=panel('Metas por valor');list.append(table(['Meta','Objetivo','Realizado','Atingido','Falta','Situação'],tracking.map(g=>[g.nome,money(g.valor_centavos),money(g.realized),percentLabel(g.percent),money(g.remaining),g.status])),node('small','Maior objetivo primeiro. Metas encerradas preservam seu histórico.','sales-card-note'));grid.append(list);
