const notebookViews=new WeakMap(),notebookObservers=new WeakMap();
function notebookDetails(root,page){
 if(!['vendas','financeiro','estoque','clientes','colaboradores','metas'].includes(page))return;
 let views=notebookViews.get(root);if(!views){views={};notebookViews.set(root,views);}
 const decorate=()=>{
  observer.disconnect();
  const content=root.querySelector('.sales-content,.financial-content,.stock-content,.portfolio-content,.collaborator-content');
  if(content){
   let toolbar=root.querySelector('.notebook-sections');
   if(!toolbar){toolbar=node('div',undefined,'notebook-sections');root.insertBefore(toolbar,content);}
   const metrics=content.querySelector(':scope > .metrics'),panels=[...content.querySelectorAll('.dashboard-card')].filter(p=>!p.parentElement.closest('.dashboard-card'));
   const entries=[...(metrics?[{id:'metrics',label:'Indicadores',element:metrics}]:[]),...panels.map((element,index)=>({id:'panel-'+index,label:element.querySelector('h3')?.firstChild?.textContent?.trim()||'Consulta '+(index+1),element}))];
   const selected=entries.find(e=>e.id===views[page])||entries[0];
   toolbar.replaceChildren();
   if(selected){
    const names={financeiro:['Fluxo','Recebimentos','A pagar','A receber'],vendas:['Evolução','Desempenho','Produtos','Clientes','Modalidades'],estoque:['Atenção','Situação','Mais vendidos','Posição'],clientes:['Ranking','Participação','Frequência'],colaboradores:['Desempenho','Vendas','Identificação','Acompanhamento'],metas:['Meta selecionada','Evolução','Ranking','Ritmo']};
    toolbar.setAttribute('role','group');toolbar.setAttribute('aria-label','Visualizações do painel');views[page]=selected.id;
    for(const entry of entries){
     entry.element.classList.add('notebook-panel');entry.element.classList.toggle('notebook-active',entry===selected);
     const label=entry.id==='metrics'?'Indicadores':names[page]?.[Number(entry.id.split('-')[1])]||entry.label;
     const button=node('button',label,'notebook-view');button.type='button';button.dataset.view=entry.id;button.title=entry.label;button.setAttribute('aria-pressed',String(entry===selected));
     button.addEventListener('click',()=>{views[page]=entry.id;decorate();root.querySelector(`.notebook-view[data-view="${entry.id}"]`)?.focus({preventScroll:true});});toolbar.append(button);
    }
   }
   for(const wrap of content.querySelectorAll('.table-scroll')){
    if(wrap.querySelector('.notebook-pagination'))continue;
    const rows=[...wrap.querySelectorAll('tbody > tr')];if(rows.length<=4)continue;
    let index=0;const pager=node('div',undefined,'notebook-pagination'),previous=node('button','Anterior','sale-toggle'),next=node('button','Próxima','sale-toggle'),count=node('span');previous.type=next.type='button';count.setAttribute('aria-live','polite');
    const draw=()=>{for(const [i,row] of rows.entries())row.classList.toggle('notebook-row-hidden',i<index||i>=index+4);count.textContent=`${index+1}–${Math.min(index+4,rows.length)} de ${rows.length}`;previous.disabled=index===0;next.disabled=index+4>=rows.length;};
    previous.addEventListener('click',()=>{index=Math.max(0,index-4);draw();});next.addEventListener('click',()=>{index+=4;draw();});pager.append(previous,count,next);wrap.append(pager);draw();
   }
  }
  observer.observe(root,{childList:true,subtree:true});
 };
 const observer=new MutationObserver(records=>{if(records.every(r=>r.target.closest?.('.notebook-pagination,.notebook-sections')))return;decorate();});
 notebookObservers.set(root,observer);decorate();
}
export function renderDashboard(root,packet,page,start,end){
 notebookObservers.get(root)?.disconnect();
 const focusedSearch=['vendas','estoque','clientes'].includes(page)&&root.contains(document.activeElement)&&document.activeElement?.type==='search',selection=focusedSearch?document.activeElement.selectionStart:null;
 root.replaceChildren();document.body?.classList.toggle('pulso-overview',page==='inicio');document.body?.classList.toggle('pulso-sales',page==='vendas');document.body?.classList.toggle('pulso-detail',['vendas','financeiro','colaboradores','estoque','clientes','metas'].includes(page));const data=packet.data,s=selected(data,start,end);
 const date=value=>value?value.split('-').reverse().join('/'):'—';
 if(page==='ajuda'){
 const help=panel('FAQ e ajuda');
 for(const [question,answer] of [
 ['De onde vêm os dados?','O Pulso apresenta a última cópia confirmada dos dados sincronizados do Nexo. As vendas consideram dias fechados e seus complementos.'],
 ['Como atualizar o painel?','Use Consultar agora para buscar os dados da base central. Recarregar painel lê a cópia disponível neste computador.'],
 ['Como funciona o período?','De e Até selecionam as datas operacionais. No Financeiro, selecionam o vencimento. Estoque mostra a posição mais recente; as metas consideram seu período integral.'],
 ['Por que aparece Não informado?','Quando não há informação suficiente, o Pulso sinaliza a ausência. Por exemplo, lucro exige custos completos das vendas.'],
 ['Como abrir Nexo e Lume?','Use os botões no menu. O acesso depende da permissão e contratação da empresa; a sessão é aproveitada entre os módulos.'],
 ['Posso acessar pelo celular?','O visual se adapta ao celular. Nesta validação, o serviço funciona apenas no computador instalado; o acesso remoto será configurado separadamente.']
 ]){const item=node('details'),title=node('summary',question);item.append(title,node('p',answer));help.append(item);}root.append(help);mountLocalHelp(root,'Pulso',[...help.querySelectorAll('details')].map(item=>[item.querySelector('summary').textContent,item.querySelector('p').textContent]));
 }else if(page==='inicio'){
  renderOverview(root,data,s,start,end,date);
 }else if(page==='vendas'){
  renderSales(root,data,start,end,date);
  if(focusedSearch){const input=root.querySelector('input[type=search]');input.focus({preventScroll:true});input.setSelectionRange(selection,selection);}
 }else if(page==='estoque'){
  renderStock(root,data,start,end,date);if(focusedSearch){const input=root.querySelector('input[type=search]');input.focus({preventScroll:true});input.setSelectionRange(selection,selection);}
 }else if(page==='financeiro'){
  renderFinancial(root,data,start,end,date);
 }else if(page==='colaboradores'){
  renderCollaborators(root,data,start,end,date);
 }else if(page==='clientes'){
  renderClients(root,data,start,end,date);if(focusedSearch){const input=root.querySelector('input[type=search]');input.focus({preventScroll:true});input.setSelectionRange(selection,selection);}
 }else if(page==='metas'){
  renderGoals(root,data,start,end,date);
 }
 notebookDetails(root,page);
}
